def loss(w):
    return (w - 3) ** 2   # minimized at w = 3

def numerical_gradient(loss_fn, w, epsilon=1e-5):
    return (loss_fn(w + epsilon) - loss_fn(w - epsilon)) / (2 * epsilon)

for w in [0, 1, 3, 5]:
    print(w, numerical_gradient(loss, w))
# 0 -6.000000...   (steep downhill toward w=3)
# 1 -4.000000...
# 3  0.000000...   (at the minimum, the slope is flat)
# 5  4.000000...   (uphill if w increases further; gradient descent would decrease w)

def loss(w):
    return (w - 3) ** 2

def grad(w):
    return 2 * (w - 3)

w = 0.0
lr = 1.2   # far too large for this loss surface

for step in range(4):
    w = w - lr * grad(w)
    print(f"step {step}: w={w:.2f}, loss={loss(w):.2f}")

# step 0: w=7.20, loss=17.64
# step 1: w=-7.68, loss=114.05
# step 2: w=18.43, loss=238.28
# step 3: w=-33.17, loss=1303.83   -- growing without bound instead of shrinking

