exercises.solutionCode:
def grad(w):
    return 2 * (w - 3)

w = 0.0
lr = 0.1

for step in range(5):
    w = w - lr * grad(w)   # fixed: subtract, to move opposite the gradient
    loss = (w - 3) ** 2
    print(f"step {step}: w={w:.3f}, loss={loss:.3f}")

