def diagnose(train_loss, val_loss, threshold=0.05):
    gap = val_loss - train_loss
    if train_loss > 0.3:
        return "underfitting"
    elif gap > threshold:
        return "overfitting"
    else:
        return "good fit"

epoch_10 = diagnose(train_loss=0.05, val_loss=0.06)
epoch_50 = diagnose(train_loss=0.02, val_loss=0.25)
epoch_100 = diagnose(train_loss=0.40, val_loss=0.42)

print(epoch_10, epoch_50, epoch_100)
